package com.tradingplatform.paper;
import com.tradingplatform.market.*; import com.tradingplatform.market.websocket.MarketTick; import java.math.BigDecimal; import java.time.*; import java.util.*; import java.util.concurrent.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service;
@Service public class PaperPriceService { public record Price(BigDecimal value,Instant timestamp){} private final ConcurrentMap<String,Price> ticks=new ConcurrentHashMap<>(); private final MarketDataService market; private final Duration maxAge; public PaperPriceService(MarketDataService market,@Value("${trading.paper.max-price-age-seconds:30}") long seconds){this.market=market;maxAge=Duration.ofSeconds(seconds);} public void accept(MarketTick tick){if(tick!=null&&tick.instrumentKey()!=null&&tick.lastPrice()!=null&&tick.lastPrice().signum()>0&&tick.timestamp()!=null)ticks.put(tick.instrumentKey(),new Price(tick.lastPrice(),tick.timestamp()));} public Price current(Instrument i){Price p=ticks.get(i.instrumentKey()); if(p==null){Quote q=market.quote(i.symbol());p=new Price(q.price(),q.timestamp());} if(p.timestamp()==null||Duration.between(p.timestamp(),Instant.now()).abs().compareTo(maxAge)>0)throw new IllegalStateException("Market data is stale for "+i.symbol()); return p;} }
